+            } catch (Throwable e) {
+              LOGGER.warn("ignoring exception thrown by cancel listener", e);
+            } finally {
+              subscription.cancel();
+            }
+          }
+        });
+      }
+
+      @Override
+      public void onNext(T in) {
+        outSubscriber.onNext(in);
