+package ratpack.http.client.internal;
+
+import java.net.URI;
+import java.time.Duration;
+
+final class HttpChannelKey {
+
+  final boolean ssl;
+  final int port;
+  final String host;
+
+  // intentionally not part of the equality check
+  final Duration connectTimeout;
+
+  HttpChannelKey(URI uri, Duration connectTimeout) {
+    switch (uri.getScheme()) {
+      case "https":
+        this.ssl = true;
+        break;
+      case "http":
+        this.ssl = false;
+        break;
+      default:
+        throw new IllegalArgumentException("URI " + uri + " is not HTTP or HTTPS");
+    }
+
+    this.port = uri.getPort() < 0 ? ssl ? 443 : 80 : uri.getPort();
+    this.host = uri.getHost();
+    this.connectTimeout = connectTimeout;
+  }
+
+  @Override
+  public boolean equals(Object o) {
+    if (this == o) {
+      return true;
+    }
+    if (o == null || getClass() != o.getClass()) {
+      return false;
+    }
+
+    HttpChannelKey that = (HttpChannelKey) o;
+
+    return ssl == that.ssl && port == that.port && host.equals(that.host);
+  }
+
+  @Override
+  public int hashCode() {
+    int result = ssl ? 1 : 0;
+    result = 31 * result + port;
+    result = 31 * result + host.hashCode();
+    return result;
+  }
+
+}

