+        return;
+      }
+
+      delegateHolder.set(delegate.produce(file, bytes));
+
+      this.lastModifiedHolder.set(lastModifiedTime);
+      this.contentHolder.set(bytes);
+    } finally {
+      lock.unlock();
+    }
+  }
