+public class AppModule extends AbstractModule {
+
+
+  @Override
+  protected void configure() {
+    bind(HTTP_HANDLER).annotatedWith(Names.named(MAIN_APP_HTTP_HANDLER)).toInstance(new NoopRouter<HttpExchange>());
