+    bind(ResponseFactory.class).to(DefaultResponseFactory.class).in(Singleton.class);
+    bind(RoutingFactory.class).to(DefaultRoutingFactory.class);
+    bind(RoutingConverter.class).to(DefaultRoutingConverter.class);
