+    bind(Request.class).toProvider(RequestScope.<Request>seededKeyProvider()).in(RequestScoped.class);
+    bind(Response.class).toProvider(RequestScope.<Response>seededKeyProvider()).in(RequestScoped.class);
+  }
+
+}

