+      // Handle raw new line characters.
+      if (c == '\n' || c == '\r') {
+        if (c == '\r') { // on Windows, "\r\n" is a new line.
+          input.markReaderIndex();
+          c = input.readByte();
+          if (c != '\n') {
+            input.resetReaderIndex();
+          }
+        }
+        script.appendString("\n");
+        continue;
+      }
+      script.appendByte(c);
+    }
+
+    endScript(script);
+  }
+
+  private void startScript(Buffer script) {
+    script.appendString("parts.add(\"\"\"");
+  }
+
+  private void endScript(Buffer script) {
+    script.appendString("\"\"\")");
+  }
+
+  private void processGSstring(ChannelBuffer input, Buffer output) throws IOException {
+    output.appendString("${");
+    byte c;
+    while (input.readable()) {
+      c = input.readByte();
+      if (c != '\n' && c != '\r') {
+        output.appendByte(c);
+      }
+      if (c == '}') {
+        break;
+      }
+    }
+  }
+
+  private void groovyExpression(ChannelBuffer input, Buffer output) throws IOException {
+    output.appendString("${");
+    byte c;
+    while (input.readable()) {
+      c = input.readByte();
+      if (c == '%') {
+        c = input.readByte();
+        if (c != '>') {
+          output.appendString("%");
+        } else {
+          break;
+        }
+      }
+      if (c != '\n' && c != '\r') {
+        output.appendByte(c);
+      }
+    }
+    output.appendString("}");
+  }
+
+  private void groovySection(ChannelBuffer input, Buffer output) throws IOException {
+    output.appendString("\"\"\");");
+    byte c;
+    while (input.readable()) {
+      c = input.readByte();
+      if (c == '%') {
+        c = input.readByte();
+        if (c != '>') {
+          output.appendString("%");
+        } else {
+          break;
+        }
+      }
+
+      output.appendByte(c);
+    }
+
+    output.appendString(";\nparts.add(\"\"\"");
+  }
+
+}

